    "level": "medium",
    "touches": [
      "wallet",
      "rpc_api"
    ],
    "why": "Strict option validation will cause RPC calls with unexpected or typoed fields to fail with an error, potentially breaking poorly written scripts while preventing silent misbehavior."
  }
}
